const DEFAULT_MAX_TOOL_ROUNDS = 5;

export interface OrchestratorHooks {
  beforeSession?: (session: ChatSession) => Promise<void>;
  afterSession?: (session: ChatSession) => Promise<void>;
  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
  afterModelResponse?: (session: ChatSession, responseText: string, totalUsage?: UsageMetadata) => Promise<void>;
  onError?: (session: ChatSession, error: Error) => Promise<void>;
  /** The supported seam for an EU AI Act Art. 14 human-oversight control: fires before each known tool's executor, and a returned ToolResponse replaces the call (see docs/adding-a-tool.md); it receives the model's raw tool input and, through session, the caller's authHeaders, so a policy that logs either logs personal data and credential material; the engine asserts nothing about any policy installed here. */
  beforeToolCall?: (session: ChatSession, call: ToolCall) => Promise<ToolResponse | undefined>;
  /** Fires when the model asks for a tool round the budget refuses, after the last provider call and before afterModelResponse; a returned string reaches the user as the turn's closing text, and the engine writes none of its own (see specs/hal-engine-tool-budget/spec.md). */
  onToolBudgetExhausted?: (session: ChatSession, budget: ToolBudgetInfo) => Promise<string | undefined>;
}

export interface ToolBudgetInfo {
  maxToolRounds: number;
  requestedTools: string[];
}

type BeforeToolCall = NonNullable<OrchestratorHooks['beforeToolCall']>;
type OnToolBudgetExhausted = NonNullable<OrchestratorHooks['onToolBudgetExhausted']>;

export const TOOL_BUDGET_EXHAUSTED = 'tool_budget_exhausted';

export interface ChatOrchestrator {
  processMessage(session: ChatSession): Promise<string>;
  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
}

export interface ChatOrchestratorOptions {
  maxToolRounds?: number;
  contextConfig?: Partial<ContextConfig>;
  promptBuilderOptions?: PromptBuilderOptions;
  hooks?: OrchestratorHooks;
  sessionStore?: SessionStore;
}

interface ToolExecutionResult {
  clientMessages: OutgoingMessage[];
  suppressOutput: boolean;
}
export function createChatOrchestrator(
  provider: AIProvider,
  promptBuilder: PromptBuilder,
  toolRegistry?: ToolRegistry,
  options?: ChatOrchestratorOptions
): ChatOrchestrator {
  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
  const contextConfig = createContextConfig(options?.contextConfig);
  const toolInstructions = toolRegistry?.getPromptInstructions();
  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
  const tools = toolRegistry?.getDefinitions();
  const hooks = options?.hooks;
  const sessionStore = options?.sessionStore;

  return {
    async processMessage(session: ChatSession): Promise<string> {
      return collectText(this.processMessageStream(session));
    },

    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
      try {
        if (hooks?.beforeSession) await hooks.beforeSession(session);

        let userMessage = lastUserContent(session);

        if (hooks?.beforeUserInput) {
          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
        }

        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);

        const systemPrompt = hooks?.beforeModelResponse
          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
          : baseSystemPrompt;

        const messages: Message[] = toMessages(session.entries, contextConfig);
        let totalUsage: UsageMetadata | undefined;
        let responseText = '';

        // Bounded by the budget gate below, not the header: maxToolRounds executed rounds, maxToolRounds + 1 provider calls.
        for (let round = 0; ; round++) {
          log.info('orchestrator', 'starting round', {round});
          const pendingToolCalls: ToolCall[] = [];

          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
          responseText += outcome.text;
          totalUsage = accumulateUsage(totalUsage, outcome.usage);

          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
          if (budgetSpent(round, maxToolRounds, pendingToolCalls)) {
            const budget = {maxToolRounds, requestedTools: pendingToolCalls.map(tc => tc.name)};
            responseText += yield* closeExhaustedTurn(session, budget, hooks?.onToolBudgetExhausted);
            break;
          }

          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
          const {clientMessages, suppressOutput} = await executeToolCalls(
            pendingToolCalls,
            messages,
            session,
            toolCallRunner(toolRegistry!, session, hooks?.beforeToolCall)
          );
          log.info('orchestrator', 'tool execution complete', {
            clientMessageCount: clientMessages.length,
            clientMessageTypes: clientMessages.map(m => m.type),
            suppressOutput,
          });

          if (clientMessages.length > 0) {
            yield {type: 'tool_result' as const, clientMessages};
          }

          if (suppressOutput) {
            yield {type: 'suppress_output' as const};
          }
        }

        if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, totalUsage);
      } catch (error) {
        if (hooks?.onError) await hooks.onError(session, asError(error));
        throw error;
      } finally {
        // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
        commitStreamingEntries(session);
        try {
          if (hooks?.afterSession) await hooks.afterSession(session);
        } finally {
          await saveSession(sessionStore, session);
        }
      }
    },
  };
}

// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
function normalizeToolRounds(value: number | undefined): number {
  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
  return Math.max(0, Math.floor(value));
}

// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
  if (round < maxToolRounds) return false;
  log.warn('orchestrator', 'tool budget exhausted', {
    maxToolRounds,
    requestedTools: pendingToolCalls.map(tc => tc.name),
  });
  return true;
}

// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
async function* closeExhaustedTurn(
  session: ChatSession,
  budget: ToolBudgetInfo,
  hook?: OnToolBudgetExhausted
): AsyncGenerator<MessageChunk, string> {
  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
  if (sentence !== '') yield {type: 'text', text: sentence};
  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
  return sentence;
}

interface RoundOutcome {
  stopReason: string;
  text: string;
  usage?: UsageMetadata;
}

// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
async function* streamRound(
  provider: AIProvider,
  request: SendMessageParams,
  pendingToolCalls: ToolCall[]
): AsyncGenerator<MessageChunk, RoundOutcome> {
  let stopReason = '';
  let text = '';
  let usage: UsageMetadata | undefined;

  for await (const chunk of provider.sendMessage(request)) {
    yield chunk;
    collectToolCalls(chunk, pendingToolCalls);
    stopReason = extractStopReason(chunk) ?? stopReason;
    usage = extractUsage(chunk) ?? usage;
    if (chunk.type === 'text') text += chunk.text;
  }

  return {stopReason, text, usage};
}

// A changed message is also written back to the session's last user entry.
async function rewriteUserMessage(
  session: ChatSession,
  userMessage: string,
  hook: (session: ChatSession, userMessage: string) => Promise<string>
): Promise<string> {
  const modified = await hook(session, userMessage);
  if (modified === userMessage) return userMessage;

  updateLastUserContent(session, modified);
  return modified;
}

function lastUserContent(session: ChatSession): string {
  for (let i = session.entries.length - 1; i >= 0; i--) {
    const entry = session.entries[i];
    if (entry.role === 'user') return entry.content;
  }
  return '';
}

function updateLastUserContent(session: ChatSession, content: string): void {
  for (let i = session.entries.length - 1; i >= 0; i--) {
    const entry = session.entries[i];
    if (entry.role === 'user') {
      entry.content = content;
      return;
    }
  }
}

// One runner per round: the policy sees each known call before its executor, and an unknown name keeps the registry's own path.
function toolCallRunner(toolRegistry: ToolRegistry, session: ChatSession, beforeToolCall?: BeforeToolCall) {
  const context: ToolContext = {
    userId: session.userId,
    sessionId: session.sessionId,
    workspaceId: session.workspaceId,
    authHeaders: session.authHeaders,
  };

  return async (tc: ToolCall): Promise<ToolResponse> => {
    const declined =
      beforeToolCall && toolRegistry.has(tc.name) ? await consultPolicy(beforeToolCall, session, tc) : undefined;
    return declined ?? toolRegistry.execute(tc.name, tc.input, context);
  };
}

// A throwing policy declines its call rather than failing the turn: every tool_use must still be answered.
async function consultPolicy(
  policy: BeforeToolCall,
  session: ChatSession,
  tc: ToolCall
): Promise<ToolResponse | undefined> {
  try {
    return await policy(session, tc);
  } catch (error) {
    log.warn('orchestrator', 'beforeToolCall threw, so the call is declined', {
      tool: tc.name,
      errorType: error instanceof Error ? error.name : typeof error,
    });
    return {result: `The ${tc.name} call was declined and not performed.`};
  }
}

async function executeToolCalls(
  pendingToolCalls: ToolCall[],
  messages: Message[],
  session: ChatSession,
  runToolCall: (tc: ToolCall) => Promise<ToolResponse>
): Promise<ToolExecutionResult> {
  messages.push(buildToolCallMessages(pendingToolCalls));

  const responses = await Promise.all(
    pendingToolCalls.map(async tc => {
      const response = await runToolCall(tc);
      return {tc, response};
    })
  );

  const toolResults: ToolResultContent[] = responses.map(({tc, response}) => ({
    type: 'tool_result' as const,
    toolUseId: tc.id,
    content: response.result,
  }));
  messages.push({role: 'user', content: toolResults});

  const rawClientMessages = responses.flatMap(({response}) => response.clientMessages ?? []);

  return {
    clientMessages: assignEntryIndices(rawClientMessages, session),
    suppressOutput: responses.some(({response}) => response.suppressAssistantResponse === true),
  };
}

function assignEntryIndices(clientMessages: OutgoingMessage[], session: ChatSession): OutgoingMessage[] {
  return clientMessages.map(msg => {
    if (msg.type !== 'entry_upsert') return msg;
    const index = appendEntry(session, msg.entry);
    return {...msg, index};
  });
}

// Adds per-round token counts so the hook receives the total across all provider calls in the turn.
function accumulateUsage(acc: UsageMetadata | undefined, next: UsageMetadata | undefined): UsageMetadata | undefined {
  if (!acc) return next;
  if (!next) return acc;
  return {
    inputTokens: acc.inputTokens + next.inputTokens,
    outputTokens: acc.outputTokens + next.outputTokens,
    totalTokens: acc.totalTokens + next.totalTokens,
  };
}

// The hook is typed against Error, so a rejection that is not one is wrapped with the original as cause; the rethrow stays the original value.
function asError(rejection: unknown): Error {
  if (rejection instanceof Error) return rejection;
  return new Error(typeof rejection === 'string' ? rejection : inspect(rejection), {cause: rejection});
}

// A store outage is not a reason to fail the turn the customer already received.
async function saveSession(store: SessionStore | undefined, session: ChatSession): Promise<void> {
  if (!store?.save) return;

  try {
    await store.save(session);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    log.error('orchestrator', 'session save failed', {sessionId: session.sessionId, error: message});
  }
}

import {readFileSync} from 'node:fs';
import {dirname, basename, join} from 'node:path';
import {fileURLToPath} from 'node:url';
import eslint from '@eslint/js';
import markdown from '@eslint/markdown';
import reLint from '@re-cinq/eslint-plugin-re-lint';
import tseslint from 'typescript-eslint';
import {parse as parseYaml} from 'yaml';

// layers.yaml is the readable declaration of the architecture; this hands it
// to no-cross-layer-import.
//
// The rule keys packages by `<package>/src/`, which suits a monorepo of
// packages and not a single package whose code sits at ./src. Left to find
// layers.yaml itself the rule would resolve every file as `src/...`, match no
// package, and report nothing - adopted in appearance, enforcing nothing. So
// the entries are re-homed under this checkout's own directory name with the
// root moved one level up, which is the shape the matcher expects.
//
// Paths come from this file's own URL rather than process.cwd(), so running
// eslint from a subdirectory cannot silently disable the rule.
// scripts/eslint-layers.test.ts fails if this ever stops reporting.
const repoRoot = dirname(fileURLToPath(import.meta.url));
const declaredLayers = parseYaml(readFileSync(join(repoRoot, 'layers.yaml'), 'utf8')).layers.src;

// Shared with eslint.config.backlog.mjs, which lints the same tree under the
// two rules held out of the blocking gate. One list, so the two configs cannot
// drift into disagreeing about what is even a source file.
//
// .claude/** is vendored agent tooling, maintained upstream rather than
// here, so a change there must not be able to redden this repo's CI.
export const ignores = [
  'node_modules/**',
  'dist/**',
  'coverage/**',
  '.claude/**',
  // Deliberately broken specs and ADRs - dead links, absent lead paragraphs,
  // statuses no parser reads - kept as the fixtures the script tests assert
  // against. Linting them would report the very faults they exist to reproduce.
  'scripts/fixtures/**',
];

export default tseslint.config(
  {ignores},
  {
    // Scoped to TypeScript now that markdown is linted too: an unscoped block
    // applies to every language, and JS rules do not survive a markdown AST.
    files: ['**/*.ts'],
    extends: [eslint.configs.recommended, ...tseslint.configs.recommended],
    plugins: {'re-lint': reLint},
    rules: {
      // CLAUDE.md leads with five mandatory layers and "no cross-layer
      // shortcuts, no circular deps". layers.yaml states that as data and this
      // rule enforces it, so the architecture is a file someone can read rather
      // than a habit that erodes.
      're-lint/no-cross-layer-import': [
        'error',
        {root: dirname(repoRoot), layers: {[basename(repoRoot)]: declaredLayers}},
      ],
      '@typescript-eslint/no-unused-vars': [
        'error',
        {
          vars: 'all',
          args: 'after-used',
          argsIgnorePattern: '^_',
          varsIgnorePattern: '^_',
          caughtErrorsIgnorePattern: '^_',
          ignoreRestSiblings: false,
        },
      ],
      camelcase: 'error',
      // CLAUDE.md: "Tests live next to source: src/**/*.test.ts". True of all
      // ten test files today; this keeps it true.
      're-lint/require-colocated-tests': 'error',
      're-lint/no-commented-out-code': 'error',
      // The provider layer must surface failures as AIError rather than
      // swallowing them and fabricating a return value (CLAUDE.md, Adding a
      // provider).
      're-lint/no-catch-as-control-flow': 'error',
      // Markdown is excluded because a doc quoting the code it documents is
      // the intended state: README's example of createHalEngine and the
      // interface blocks in specs/ are *supposed* to match src/. jscpd extracts
      // fenced blocks and reports them as clones, so without this every
      // accurate code sample is a lint error and the incentive is to let the
      // docs drift. The same exclusion a jscpd config would carry; it lives
      // here rather than in a .jscpd.json because the rule reads `ignore` from
      // its own options and never from a config file.
      're-lint/no-duplicate-code': ['error', {ignore: ['**/*.md']}],
      're-lint/callee-below-caller': 'error',
      're-lint/declare-near-use': 'error',
      're-lint/default-export-matches-filename': 'error',
      're-lint/max-boolean-operators': 'error',
      're-lint/max-comment-lines': 'error',
      're-lint/max-member-chain': 'error',
      're-lint/no-closing-brace-comments': 'error',
      're-lint/no-flag-params': 'error',
      // INERT, kept as a placeholder. It needs type information and this config
      // gives it none, so it reports nothing - verified with a textbook
      // forwarding class, which it does not flag. The rule's own docs record the
      // same finding for the same reason. It becomes a real guardrail only if
      // this config adopts parserOptions.projectService; until then it is not
      // one, and a clean run says nothing about forwarding classes.
      're-lint/no-forwarding-class': 'error',
      're-lint/no-hybrid-class': 'error',
      're-lint/no-negative-names': 'error',
      're-lint/no-nested-if': 'error',
      're-lint/no-nested-loop': 'error',
      're-lint/no-reexport-only-module': 'error',
      're-lint/no-vague-names': 'error',
      're-lint/prefer-early-return': 'error',
      're-lint/prefer-polymorphism': 'error',
      're-lint/require-fetch-timeout': 'error',
      'no-console': 'error',
      // Providers are loaded lazily so that selecting one never forces its SDK
      // on consumers of the others, and the factories doing it are synchronous
      // (`createProvider`, `createBedrockProvider`) - dynamic `import()` would
      // make them async, which is a breaking API change. The rule stays on and
      // still rejects every other `require()`; only these paths are permitted.
      '@typescript-eslint/no-require-imports': [
        'error',
        {allow: ['^\\./(bedrock|vertex|openai|anthropic|mock)/index\\.js$', '^@aws-sdk/client-bedrock-runtime$']},
      ],
    },
  },
  // Rules that only make sense on a test file.
  {
    // require-spec-link gates here: every test in
    // the suite cites a spec statement, so the backlog it once measured is
    // empty and an uncited new test is now a build failure rather than a
    // number. Its statement-side mirror stays a report - see
    // eslint.config.backlog.mjs.
    files: ['**/*.test.ts'],
    plugins: {'re-lint': reLint},
    rules: {
      're-lint/require-spec-link': 'error',
      're-lint/max-expects': 'error',
      're-lint/no-nondeterministic-tests': 'error',
      're-lint/test-imports-its-subject': 'error',
    },
  },
  // Every markdown link to a repo file must land. A rename sweep rewrites a
  // dead link faithfully and the reference still reads as current, which is
  // exactly how the spec restructure could have gone wrong.
  {
    files: ['**/*.md'],
    language: 'markdown/gfm',
    plugins: {markdown, 're-lint': reLint},
    rules: {'re-lint/no-dead-md-links': 'error'},
  },
  // AGENTS.md § Spec Header Table: every spec and ADR opens with a lead
  // paragraph, and a spec's `| Status |` row must match its test-citation
  // coverage. ADRs are exempt from the coverage tier - asking a decision
  // record to cite a test for every statement it makes is the wrong ask - so
  // the second rule is scoped to specs alone.
  {
    files: ['specs/**/spec.md', 'adrs/*.md', 'scripts/fixtures/spec-status/**/*.md'],
    language: 'markdown/gfm',
    plugins: {markdown, 're-lint': reLint},
    rules: {'re-lint/require-intro-paragraph': 'error'},
  },
  {
    files: ['specs/**/spec.md', 'scripts/fixtures/spec-status/specs/**/spec.md'],
    language: 'markdown/gfm',
    plugins: {markdown, 're-lint': reLint},
    // require-statement-links belongs to this pair but is deliberately absent:
    // see eslint.config.backlog.mjs.
    rules: {'re-lint/require-status-matches-coverage': 'error'},
  }
);

